   305	/**
   306	 * Checks if a token for a central or local header has been found and resets
   307	 * the device to the begin of the token. If a token for the data descriptor is
   308	 * found it is assumed there is a central or local header token starting right
   309	 * behind the data descriptor, and the device is set accordingly to the begin
   310	 * of that token.
   311	 * To be called when a 'P' has been found.
   312	 * @param buffer start of buffer with the 3 bytes behind 'P'
   313	 * @param dev device that is read from
   314	 * @param dataDescriptor only search for data descriptor
   315	 * @return true if a local or central header begin is or could be reached
   316	 */
   317	static bool handlePossibleHeaderBegin(const char *buffer, QIODevice *dev, bool dataDescriptor)
   318	{
   319	    // we have to detect three magic tokens here:
   320	    // PK34 for the next local header in case there is no data descriptor
   321	    // PK12 for the central header in case there is no data descriptor
   322	    // PK78 for the data descriptor in case it is following the compressed data
   323	    // TODO: optimize using 32bit const data for comparison instead of byte-wise,
   324	    // given we run at least on 32bit CPUs
   325	
   326	    if (buffer[0] == 'K') {
   327	        if (buffer[1] == 7 && buffer[2] == 8) {
   328	            // data descriptor token found
   329	            dev->seek(dev->pos() + 12); // skip the 'data_descriptor'
   330	            return true;
   331	        }
   332	
   333	        if (!dataDescriptor && ((buffer[1] == 1 && buffer[2] == 2)
   334	            || (buffer[1] == 3 && buffer[2] == 4))) {
   335	            // central/local header token found
   336	            dev->seek(dev->pos() - 4);
   337	            // go back 4 bytes, so that the magic bytes can be found
   338	            // in the next cycle...
   339	            return true;
   340	        }
   341	    }
   342	    return false;
   343	}
   344	
   345	/**
   346	 * Reads the device forwards from the current pos until a token for a central or
   347	 * local header has been found or is to be assumed.
   348	 * @param dev device that is read from
   349	 * @return true if a local or central header token could be reached, false on error
   350	 */
   351	static bool seekToNextHeaderToken(QIODevice *dev, bool dataDescriptor)
   352	{
   353	    bool headerTokenFound = false;
   354	    char buffer[3];
   355	
   356	    while (!headerTokenFound) {
   357	        int n = dev->read(buffer, 1);
   358	        if (n < 1) {
   359	            //qCWarning(KArchiveLog) << "Invalid ZIP file. Unexpected end of file. (#2)";
   360	            return false;
   361	        }
   362	
   363	        if (buffer[0] != 'P') {
   364	            continue;
   365	        }
   366	
   367	        n = dev->read(buffer, 3);
   368	        if (n < 3) {
   369	            //qCWarning(KArchiveLog) << "Invalid ZIP file. Unexpected end of file. (#3)";
   370	            return false;
   371	        }
   372	
   373	        if (handlePossibleHeaderBegin(buffer, dev, dataDescriptor)) {
   374	            headerTokenFound = true;
   375	        } else {
   376	            for (int i = 0; i < 3; ++i) {
   377	                if (buffer[i] == 'P') {
   378	                    // We have another P character so we must go back a little to check if it is a magic
   379	                    dev->seek(dev->pos() - 3 + i);
   380	                    break;
   381	                }
   382	            }
   383	        }
   384	    }
   385	    return true;
   386	}
